package io.agora.media; import org.apache.commons.codec.binary.Base64; import java.security.SecureRandom; import java.util.Date; import java.util.zip.*; import java.io.*; public class Utils { public static int VERSION_LENGTH=3; public static int getTimestamp(){ return (int)((new Date().getTime())/1000);} public static int randomInt(){ return new SecureRandom().nextInt(); } public static boolean isUUID(String uuid){ return uuid.length()==32 && uuid.matches("\\p{XDigit}+"); } public static String base64Encode(byte[] data){ return new String(Base64.encodeBase64(data)); } public static byte[] compress(byte[] data){ Deflater d=new Deflater(); ByteArrayOutputStream bos=new ByteArrayOutputStream(data.length); try{ d.setInput(data); d.finish(); byte[] buf=new byte[data.length]; while(!d.finished()){ int i=d.deflate(buf); bos.write(buf,0,i);} }catch(Exception ignored){} finally{ d.end(); } return bos.toByteArray(); } }
